fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n < 4 {
                4 - n
            } else {
                // n >= 4, so we just need 0 if even, 1 if odd
                n % 2
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_various() {
        // For n < 4: answer is 4 - n
        assert_eq!(solve(vec![2]), vec![2]); // need 2 to reach 4
        assert_eq!(solve(vec![3]), vec![1]); // need 1 to reach 4

        // For n >= 4: answer is parity
        assert_eq!(solve(vec![4]), vec![0]); // already even & ≥4
        assert_eq!(solve(vec![5]), vec![1]); // needs 1 to become even
        assert_eq!(solve(vec![6]), vec![0]); // already even
        assert_eq!(solve(vec![7]), vec![1]); // needs 1

        // Mixed queries
        let input = vec![2, 3, 4, 5, 6, 7];
        let expected = vec![2, 1, 0, 1, 0, 1];
        assert_eq!(solve(input), expected);
    }
}